/**
 * Part 1 R1 / C1 — the consumer-contract tokens exist where the README says they do,
 * and a Tailwind build of the request's fixture classes reads the matching variables.
 *
 * The README table is generated by scripts/build-llms.mjs (contract tokens + every
 * token a registry item maps via cssVars.theme); this suite reads that table, so a
 * token added to a registry item without a value in globals.css fails here.
 */
import { describe, expect, it } from "vitest";
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { compile } from "tailwindcss";

const ROOT = path.resolve(__dirname, "..");
const globals = fs.readFileSync(path.join(ROOT, "src", "app", "globals.css"), "utf8").replace(/\r\n/g, "\n");
const readme = fs.readFileSync(path.join(ROOT, "README.md"), "utf8").replace(/\r\n/g, "\n");

/** Body of the first top-level block whose selector line matches `selector` and that contains `probe`. */
function block(selector: RegExp, probe: string) {
  const re = new RegExp(`^${selector.source}\\s*\\{\\n([\\s\\S]*?)^\\}`, "gm");
  for (const m of globals.matchAll(re)) if (m[1].includes(probe)) return m[1];
  throw new Error(`no ${selector} block containing ${probe}`);
}
const root = block(/:root/, "--background:");
const dark = block(/\.dark/, "--background:");
const theme = block(/@theme inline/, "--color-background:");

const tableTokens = (() => {
  const s = readme.indexOf("<!-- GENERATED TOKENS");
  const e = readme.indexOf("<!-- END GENERATED TOKENS -->");
  return [...readme.slice(s, e).matchAll(/^\| `--([a-z0-9-]+)` \|/gm)].map((m) => m[1]);
})();

describe("README token table ⇔ globals.css", () => {
  it("lists the contract tokens the request names", () => {
    expect(tableTokens).toEqual(
      expect.arrayContaining([
        "brand",
        "brand-foreground",
        "success",
        "success-foreground",
        "info",
        "info-foreground",
        "story-ring-from",
        "story-ring-to",
        "destructive-foreground",
      ]),
    );
  });

  it.each(tableTokens)("--%s is defined under :root, under .dark, and mapped in @theme inline", (t) => {
    expect(root, `:root --${t}`).toMatch(new RegExp(`^\\s*--${t}:`, "m"));
    expect(dark, `.dark --${t}`).toMatch(new RegExp(`^\\s*--${t}:`, "m"));
    expect(theme, `@theme --color-${t}`).toMatch(new RegExp(`^\\s*--color-${t}:\\s*var\\(--${t}\\b`, "m"));
  });

  it("keeps --accent neutral (distinct from --brand)", () => {
    const accent = root.match(/^\s*--accent:\s*([^;]+);/m)?.[1] ?? "";
    const brand = root.match(/^\s*--brand:\s*([^;]+);/m)?.[1] ?? "";
    expect(accent).not.toBe(brand);
    expect(Number(accent.match(/oklch\(\s*[\d.]+\s+([\d.]+)/)?.[1] ?? 1)).toBeLessThan(0.02);
  });
});

describe("Tailwind build of the request's fixture", () => {
  it("emits rules that read the matching variables", async () => {
    const require = createRequire(path.join(ROOT, "package.json"));
    const twDir = path.dirname(require.resolve("tailwindcss/package.json"));
    const css = [
      '@import "tailwindcss/theme.css" layer(theme);',
      '@import "tailwindcss/utilities.css" layer(utilities);',
      `@theme inline {\n${theme}}`,
    ].join("\n");
    const compiler = await compile(css, {
      base: ROOT,
      loadStylesheet: async (id: string, base: string) => {
        const file = id.startsWith("tailwindcss/") ? path.join(twDir, id.slice("tailwindcss/".length)) : path.resolve(base, id);
        return { path: file, base: path.dirname(file), content: fs.readFileSync(file, "utf8") };
      },
    });
    const out = compiler.build([
      "bg-brand",
      "text-brand-foreground",
      "bg-success",
      "text-info-foreground",
      "from-story-ring-from",
      "to-story-ring-to",
      "text-destructive-foreground",
      "bg-media-overlay",
    ]);
    for (const [cls, v] of [
      ["bg-brand", "--brand"],
      ["text-brand-foreground", "--brand-foreground"],
      ["bg-success", "--success"],
      ["text-info-foreground", "--info-foreground"],
      ["from-story-ring-from", "--story-ring-from"],
      ["to-story-ring-to", "--story-ring-to"],
      ["text-destructive-foreground", "--destructive-foreground"],
      ["bg-media-overlay", "--media-overlay"],
    ]) {
      const rule = out.match(new RegExp(`\\.${cls}\\s*\\{([^}]*)\\}`))?.[1] ?? "";
      expect(rule, cls).toContain(`var(${v}`);
    }
  });
});
